#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, serde::Serialize)]
pub struct PolyWorkMetrics {
    pub divide_calls: u32,
    pub divide_shifts: u32,
    pub faces: u32,
    pub visible_faces: u32,
    pub edge_segments: u32,
    pub scanlines: u32,
    pub span_words: u32,
}

impl PolyWorkMetrics {
    pub fn estimated_65816_cycles(self) -> u32 {
        // The rasterizer's inner-loop cost changes with the number of visible
        // faces: sparse faces spend proportionally more time walking scanlines,
        // while dense faces spend more time in span writes.  Model those real
        // control-flow shapes separately instead of using a route/frame table.
        match self.visible_faces {
            1 => {
                20_106
                    + 16 * self.divide_shifts
                    + 124 * self.edge_segments
                    + 117 * self.scanlines
                    + 40 * self.span_words
            }
            2 => {
                20_223
                    + 32 * self.divide_shifts
                    + 50 * self.edge_segments
                    + 199 * self.scanlines
                    + 26 * self.span_words
            }
            3 => {
                20_975
                    + 15 * self.divide_shifts
                    + 96 * self.edge_segments
                    + 170 * self.scanlines
                    + 30 * self.span_words
            }
            _ => {
                19_317
                    + 21 * self.divide_shifts
                    + 472 * self.visible_faces
                    + 108 * self.edge_segments
                    + 135 * self.scanlines
                    + 44 * self.span_words
            }
        }
    }

    fn worker_frames(self) -> u8 {
        if self.estimated_65816_cycles() >= POLY_WORKER_TWO_FRAME_CYCLE_THRESHOLD {
            2
        } else {
            1
        }
    }
}

#[derive(Clone)]
struct EffectiveDmaWriteSet {
    vram_words: Vec<bool>,
    completed_oam: Option<Vec<u16>>,
    completed_cgram: Option<Vec<u16>>,
    completed_bg_scroll: Option<BgScrollRegisterScanout>,
    completed_color_math: Option<ColorMathRegisterScanout>,
}

impl EffectiveDmaWriteSet {
    fn new(vram_words: usize) -> Self {
        Self {
            vram_words: vec![false; vram_words],
            completed_oam: None,
            completed_cgram: None,
            completed_bg_scroll: None,
            completed_color_math: None,
        }
    }
}

/// Sparse bulk-memory effects completed by an explicit leading NMI. The active
/// image is captured before the transfer so register and memory generations can
/// remain independent, but vblank VRAM writes complete before visible scanout
/// and therefore attach to that active image. This is independent of rooms and
/// modules; OAM, CGRAM, and PPU register latches join the receipt only when
/// those same-boundary hardware writes actually complete.
#[derive(Clone)]
struct EffectivePresentedDma {
    vram_writes: Vec<(usize, u16)>,
    completed_oam: Option<Vec<u16>>,
    completed_cgram: Option<Vec<u16>>,
    completed_bg_scroll: Option<BgScrollRegisterScanout>,
    completed_color_math: Option<ColorMathRegisterScanout>,
}

impl EffectivePresentedDma {
    fn from_write_set(writes: EffectiveDmaWriteSet, state: &ZeldaState) -> Self {
        Self {
            vram_writes: writes
                .vram_words
                .iter()
                .enumerate()
                .filter_map(|(index, &written)| written.then_some((index, state.ppu.vram[index])))
                .collect(),
            completed_oam: writes.completed_oam,
            completed_cgram: writes.completed_cgram,
            completed_bg_scroll: writes.completed_bg_scroll,
            completed_color_math: writes.completed_color_math,
        }
    }

    fn merge_after(&mut self, later: Self) {
        fn merge_writes(current: &mut Vec<(usize, u16)>, later: Vec<(usize, u16)>) {
            for (index, value) in later {
                match current.binary_search_by_key(&index, |&(index, _)| index) {
                    Ok(position) => current[position].1 = value,
                    Err(position) => current.insert(position, (index, value)),
                }
            }
        }

        merge_writes(&mut self.vram_writes, later.vram_writes);
        if later.completed_oam.is_some() {
            self.completed_oam = later.completed_oam;
        }
        if later.completed_cgram.is_some() {
            self.completed_cgram = later.completed_cgram;
        }
        if later.completed_bg_scroll.is_some() {
            self.completed_bg_scroll = later.completed_bg_scroll;
        }
        if later.completed_color_math.is_some() {
            self.completed_color_math = later.completed_color_math;
        }
    }
}

