    pub(super) fn capture_dungeon_state_12_cpu_advance_before_leading_nmi(&mut self) {
        let frame = self.game_state.frame;
        if self.rom_startup_timing()
            && frame.main_module == 7
            && frame.submodule == 2
            && frame.subsubmodule == 12
        {
            if self.dungeon_landing_cpu_advance_pending.is_none() {
                let advance = begin_dungeon_supertile_state_12_cpu_advance(self);
                self.dungeon_landing_cpu_advance_pending = Some(advance);
            }
        }
        if self.rom_startup_timing()
            && frame.main_module == 7
            && frame.submodule == 0x0e
            && matches!(frame.subsubmodule, 3 | 6 | 7 | 19)
            && self.game_execution_scheduler.is_idle()
            && self.dungeon_submodule_cpu_schedule.is_none()
        {
            let schedule = dungeon_submodule_cpu_schedule(self);
            if env::var_os("ZELDA3_DEBUG_DUNGEON_CPU_SCHEDULE").is_some() {
                eprintln!(
                    "dungeon_cpu_schedule host={} module={:02x}/{:02x}/{:02x} submodule_nmis={} caller_nmis={} sprite_main_nmis={} suffix_nmis={} after_slot={:?} reenters_main={}",
                    self.frame_ctr_dbg,
                    frame.main_module,
                    frame.submodule,
                    frame.subsubmodule,
                    schedule.submodule_nmis,
                    schedule.caller_nmis,
                    schedule.caller_sprite_main_nmis,
                    schedule.caller_suffix_nmis,
                    schedule.sprite_main_nmi_after_slot,
                    schedule.reenters_main_loop_before_nmi,
                );
            }
            self.dungeon_submodule_cpu_schedule = Some(schedule);
        }
    }

    pub(super) fn suspend_dungeon_subtile_palette_filter_if_cpu_interrupted(&mut self) {
        let Some(advance) = self.dungeon_palette_cpu_advance_pending.take() else {
            return;
        };
        debug_assert_eq!(
            advance.subsubmodule, self.game_state.frame.subsubmodule,
            "subtile palette ROM shadow and translated body disagree at PC {:06x}",
            advance.pc,
        );
        debug_assert_eq!(
            advance.palette_countdown,
            self.game_state.display.palette_filter.countdown(),
            "subtile palette ROM shadow and translated palette disagree at PC {:06x}",
            advance.pc,
        );
        if advance.work.was_interrupted() {
            self.game_execution_scheduler.schedule_work(
                GameWorkContinuation::FinishDungeonSubtilePaletteFilter,
                DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
            );
        }
    }

    pub(super) fn suspend_straight_interroom_fadeout_suffix_if_crosses_nmi(
        &mut self,
        palette_countdown: u8,
    ) {
        let frame = self.game_state.frame;
        if self.rom_startup_timing()
            && straight_interroom_fadeout_suffix_crosses_vblank(
                frame.main_module,
                frame.submodule,
                frame.subsubmodule,
                self.game_state.world.location.dungeon_room_index(),
                self.game_state.dungeon.stair_movement.staircase_index(),
                palette_countdown,
            )
        {
            self.game_execution_scheduler.schedule_work(
                GameWorkContinuation::FinishStraightInterroomFadeoutSuffix,
                DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
            );
        }
    }

    /// Stage the next frame's OBJ scanout generations, recording the caller's
    /// source location so the display probe (`ZELDA3_DEBUG_DISPLAY_OAM_FRAME` /
    /// `ZELDA3_DEBUG_DISPLAY_OBJ_VRAM_FRAME`) can name which handler owns the
    /// decision. Every writer of `next_display_obj_scanout_generation` should go
    /// through here rather than assigning the field directly.
    #[track_caller]
    fn set_next_display_obj_scanout(&mut self, value: Option<ObjScanoutGenerations>) {
        if value.is_some() {
            self.next_display_obj_scanout_provenance = Some(core::panic::Location::caller());
        }
        self.next_display_obj_scanout_generation = value;
    }

    pub(super) fn stage_straight_interroom_fadeout_obj_source(&mut self) {
        if self.next_display_obj_scanout_generation.is_some() {
            // A resumed caller already staged the independently measured OAM
            // and Link-DMA generations for this capture.
            return;
        }
        let mut scanout = straight_interroom_fadeout_obj_scanout();
        // Link's raw VRAM scanout can be live while its semantic source still
        // belongs to the host-boundary operands consumed by the NMI. Preserve
        // the ordinary atomic fadeout snapshot explicit.
        scanout.link_obj_sources = GraphicsDmaGeneration::HostBoundaryBeforeMain;
        self.set_next_display_obj_scanout(Some(scanout));
    }

    pub(super) fn suspend_spiral_staircase_palette_filter(
        &mut self,
        tail: SpiralStaircasePaletteTail,
    ) -> bool {
        if !self.rom_startup_timing() {
            return false;
        }
        // The interrupted palette walk keeps NMI_DoUpdates gated until the
        // translated caller returns. In particular, the animated-BG DMA must
        // not consume the source advanced by the suspended spiral-staircase
        // main slice.
        self.set_core_update_disable_flag(1);
        let caller =
            InterruptedPaletteFilterCaller::from_dungeon_submodule(self.game_state.frame.submodule);
        self.game_execution_scheduler.schedule_work(
            GameWorkContinuation::FinishSpiralStaircasePaletteFilter { tail, caller },
            DUNGEON_SUBTILE_PALETTE_FILTER_RETURN_NMI_SLICES,
        );
        true
    }

    pub(super) fn schedule_straight_interroom_state5_after_leading_nmi(&mut self) {
        if self.rom_startup_timing()
            && self.game_state.frame.main_module == 7
            && self.game_state.frame.submodule == 0x12
            && self.game_state.frame.subsubmodule == 5
            && self.game_state.world.location.dungeon_room_index() == 0x51
            && self.game_state.dungeon.stair_movement.staircase_index() == 0x30
        {
            self.game_execution_scheduler
                .schedule_pre_main_nmi_resume(PreMainNmiResume::StraightInterroomState5LeadingNmi);
        }
    }

    pub(super) fn suspend_straight_interroom_sprite_reset_before_room_load(&mut self) -> bool {
        if !self.rom_startup_timing()
            || self.game_state.frame.main_module != 7
            || self.game_state.frame.submodule != 0x12
            || self.game_state.frame.subsubmodule != 5
            || self.game_state.world.location.dungeon_room_index() != 0x32
            || self.game_state.dungeon.stair_movement.staircase_index() != 0x35
        {
            return false;
        }

        // On this measured staircase, vblank lands after Dungeon_ResetSprites
        // has disabled the old room's slots but before it loads the new room's
        // sprite records. Preserve that directly observable halfway state.
        self.dungeon_reset_sprites_before_room_load();
        self.game_execution_scheduler
            .schedule_work(GameWorkContinuation::FinishStraightInterroomSpriteReset, 1);
        true
    }

    pub(super) fn schedule_dungeon_faded_filter_completion_nmi(&mut self) {
        debug_assert!(self.rom_startup_timing());
        debug_assert_eq!(self.game_state.frame.main_module, 7);
        debug_assert_eq!(self.game_state.frame.submodule, 2);
        debug_assert_eq!(self.game_state.frame.subsubmodule, 3);
        debug_assert_eq!(self.game_state.display.palette_filter.countdown(), 0);
        self.stage_dungeon_faded_filter_completion_scanout();
        self.schedule_dungeon_faded_filter_leading_nmi_resume();
    }

    fn schedule_dungeon_faded_filter_leading_nmi_resume(&mut self) {
        debug_assert!(self.rom_startup_timing());
        debug_assert_eq!(self.game_state.frame.main_module, 7);
        debug_assert_eq!(self.game_state.frame.submodule, 2);
        self.game_execution_scheduler.schedule_pre_main_nmi_resume(
            PreMainNmiResume::DungeonModuleCallerCompletedBeforeNextNmi,
        );
    }

    fn stage_spiral_stairs_second_grayscale_nmi(&mut self) -> GraphicsDmaGeneration {
        // The final quadrant-upload NMI has returned, so the atomic ROM path
        // exposes $0710 = 0 to this caller. Its core DMA is allowed to run.
        // The resident animated batch remains visible for this image. When
        // this suffix consumes countdown 1 it advances $0adc before NMI, so
        // the DMA must use the live operand even though its result belongs to
        // the following scanout.
        self.clear_core_update_disable_flag();
        self.next_display_animated_bg_scanout_generation =
            Some(AnimatedBgScanoutGeneration::HostBoundaryBeforeNmi);
        if self.game_state.display.bg_tile_animation_countdown == 1 {
            GraphicsDmaGeneration::LiveAfterMain
        } else {
            GraphicsDmaGeneration::HostBoundaryBeforeMain
        }
    }

    fn link_obj_dma_phase_generations(&self) -> LinkObjDmaPhaseGenerations {
        let exit_frame = self.game_state.frame;
        let entry_frame = self
            .pre_main_graphics_dma
            .as_ref()
            .map(|graphics| graphics.entry_frame)
            .unwrap_or(exit_frame);
        link_obj_dma_generations_for_cpu_phase(
            self.game_execution_scheduler
                .resumed_call_stack_is_before_nmi(),
            link_obj_operands_across_main(
                entry_frame,
                exit_frame,
                rom_graphics_dma_plan(exit_frame.main_module, exit_frame.submodule)
                    .link_obj_operands,
            ),
        )
    }

    /// Link OBJ generation which had actually completed DMA when the current
    /// scanout was published. A resumed caller may already have authored the
    /// following source, but it is not presented until its NMI completes.
    fn presented_link_obj_dma_generation(&self) -> GraphicsDmaGeneration {
        self.link_obj_dma_phase_generations().presented
    }

    /// Link OBJ operands consumed if the following NMI runs after this CPU
    /// slice. This is intentionally distinct from the presented generation.
    fn following_nmi_link_obj_dma_generation(&self) -> GraphicsDmaGeneration {
        self.link_obj_dma_phase_generations().following_nmi
    }

